sql.where:
t.deleted = 0

    AND t.task_id = #{req.taskId}


    AND t.result_id = #{req.resultId}


    AND t.defect_code_id = #{req.defectCodeId}


    AND t.defect_code LIKE CONCAT('%', #{req.defectCode}, '%')


    AND t.defect_name LIKE CONCAT('%', #{req.defectName}, '%')


    AND t.defect_level = #{req.defectLevel}


    AND t.location LIKE CONCAT('%', #{req.location}, '%')


    AND t.create_time BETWEEN #{req.createTime[0]} AND #{req.createTime[1]}
